-- POR-1 PROMOTION P2 — Canonical recommendation sets, items and actions
--
-- PRODUCTION_LINEAGE. Generated by scripts/por1/compile-promotion.mjs from the FINAL Preview
-- catalogue — not from the 24-migration Preview history. Only the last definition of a
-- `create or replace` chain is live, so promoting the history would promote bodies that were
-- already replaced, including the ones replaced because they were wrong.
--
-- Regenerate and verify with:  npm run por1:promotion-check
--
-- CONTENTS
--   tables 3 · sequences 1 · functions 3 · triggers 0
--
-- APPLY SEMANTICS
--   Every statement is guarded (`if not exists` / catalogue probe), so a partial failure can be
--   retried without a human reconstructing which half applied.
--
-- ROLLBACK CLASS
--   SCHEMA_REVERSIBLE_WHILE_FLAGS_OFF — additive only. Nothing here alters or drops an existing
--   Production object, so with the POR-1 capability controls unset these objects are inert: the
--   old application never names them. The Production incident response is to disable the
--   capability and roll back the application, NOT to drop the schema.
--
-- EXISTING-DATA IMPACT
--   None. No backfill, no column change to a populated table, no data movement.
--
-- LOCK CLASS
--   CREATE TABLE / CREATE INDEX on brand-new empty relations. No lock is taken on any table the
--   running application reads or writes.


-- ── sequences ──────────────────────────────────────────────────────────────

create sequence if not exists public.yorisou_recommendation_actions_seq as bigint increment by 1 start with 1 no cycle;
do $$ begin
  execute 'revoke all on sequence public.yorisou_recommendation_actions_seq from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on sequence public.yorisou_recommendation_actions_seq from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on sequence public.yorisou_recommendation_actions_seq from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant usage, select on sequence public.yorisou_recommendation_actions_seq to service_role';
  end if;
end $$;

-- ── tables ─────────────────────────────────────────────────────────────────

-- yorisou_canonical_recommendation_sets

create table if not exists public.yorisou_canonical_recommendation_sets (
  id uuid default gen_random_uuid() not null,
  result_row_id uuid not null,
  owner_account_id text not null,
  accepted_result_id text not null,
  original_result_id text,
  eligibility_basis text not null,
  content_version text not null,
  source_surface text not null,
  generated_at timestamp with time zone default now() not null,
  lifecycle_state text default 'active'::text not null,
  created_at timestamp with time zone default now() not null
);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'yorisou_canonical_recommendation_sets_eligibility_basis_check' and conrelid = 'public.yorisou_canonical_recommendation_sets'::regclass) then
    alter table public.yorisou_canonical_recommendation_sets add constraint yorisou_canonical_recommendation_sets_eligibility_basis_check CHECK ((eligibility_basis = ANY (ARRAY['confirmed'::text, 'corrected'::text])));
  end if;
end $$;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'yorisou_canonical_recommendation_sets_lifecycle_state_check' and conrelid = 'public.yorisou_canonical_recommendation_sets'::regclass) then
    alter table public.yorisou_canonical_recommendation_sets add constraint yorisou_canonical_recommendation_sets_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['active'::text, 'superseded'::text, 'withdrawn'::text])));
  end if;
end $$;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'yorisou_canonical_recommendation_sets_pkey' and conrelid = 'public.yorisou_canonical_recommendation_sets'::regclass) then
    alter table public.yorisou_canonical_recommendation_sets add constraint yorisou_canonical_recommendation_sets_pkey PRIMARY KEY (id);
  end if;
end $$;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'yorisou_canonical_recommendation_sets_result_row_id_fkey' and conrelid = 'public.yorisou_canonical_recommendation_sets'::regclass) then
    alter table public.yorisou_canonical_recommendation_sets add constraint yorisou_canonical_recommendation_sets_result_row_id_fkey FOREIGN KEY (result_row_id) REFERENCES yorisou_assessment_results(id) ON DELETE CASCADE;
  end if;
