do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'yorisou_canonical_recommendation_sets_source_surface_check' and conrelid = 'public.yorisou_canonical_recommendation_sets'::regclass) then
    alter table public.yorisou_canonical_recommendation_sets add constraint yorisou_canonical_recommendation_sets_source_surface_check CHECK ((source_surface = ANY (ARRAY['result'::text, 'recommendations'::text, 'graph'::text, 'private_state'::text, 'line'::text])));
  end if;
end $$;

create index if not exists yorisou_canonical_recommendation_sets_owner ON public.yorisou_canonical_recommendation_sets USING btree (owner_account_id, result_row_id, generated_at DESC);

alter table public.yorisou_canonical_recommendation_sets enable row level security;

alter table public.yorisou_canonical_recommendation_sets force row level security;

revoke all on table public.yorisou_canonical_recommendation_sets from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on table public.yorisou_canonical_recommendation_sets from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on table public.yorisou_canonical_recommendation_sets from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
